package com.game_manager.gm.machine;
import com.game_manager.gm.security.JwtService;import io.jsonwebtoken.JwtException;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.time.Clock;import java.util.List;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;
@Component public class MachineAuthenticationFilter extends OncePerRequestFilter {private final JwtService jwt;private final StationMachineIdentityRepository identities;private final Clock clock;public MachineAuthenticationFilter(JwtService j,StationMachineIdentityRepository i,Clock c){jwt=j;identities=i;clock=c;}
 @Override protected boolean shouldNotFilter(HttpServletRequest r){return !r.getRequestURI().startsWith("/api/v1/machine/");}
 @Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{String header=request.getHeader("Authorization");if(header!=null&&header.startsWith("Bearer "))authenticate(header.substring(7));chain.doFilter(request,response);}
 private void authenticate(String token){try{var claims=jwt.parseMachine(token);StationMachineIdentity identity=identities.findById(claims.identityId()).orElse(null);if(identity==null||!identity.getStationId().equals(claims.stationId())||identity.getKeyVersion()!=claims.keyVersion()||identity.getStatus()==MachineIdentityStatus.REVOKED||(identity.getStatus()==MachineIdentityStatus.ROTATING&&(identity.getOverlapExpiresAt()==null||!identity.getOverlapExpiresAt().isAfter(clock.instant())))){SecurityContextHolder.clearContext();return;}MachinePrincipal principal=new MachinePrincipal(identity.getId(),identity.getStationId(),identity.getKeyVersion());SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(principal,null,List.of(new SimpleGrantedAuthority("MACHINE_PROTOCOL"))));}catch(JwtException|IllegalArgumentException e){SecurityContextHolder.clearContext();}}
}
